const PLANOS_EMPRESA={basico:{nome:'Grátis',vagas:3,destaques:0,urgentes:0,confidenciais:0},mensal:{nome:'Mensal',vagas:6,destaques:1,urgentes:1,confidenciais:0},trimestral:{nome:'Trimestral',vagas:12,destaques:3,urgentes:3,confidenciais:2},semestral:{nome:'Semestral',vagas:25,destaques:5,urgentes:5,confidenciais:4},anual:{nome:'Anual',vagas:60,destaques:10,urgentes:10,confidenciais:8}};
function selecionarPlano(p){if(papelAtual()!=='empresa'){sessionStorage.setItem('planoPretendido',p);irPara('login-empresa');return}const empresas=ler('empregaMaisEmpresas'),cnpj=sessionStorage.getItem('empresaCnpj'),i=empresas.findIndex(e=>e.cnpj===cnpj);if(i<0)return;const pedidosExistentes=ler('empregaMaisPedidosPlano');if(p!=='basico'&&pedidosExistentes.some(x=>x.empresaCnpj===cnpj&&x.plano===p&&x.status==='aguardando_pagamento'))return msg('#msgPlano','Este plano já possui uma solicitação aguardando pagamento.');if(p==='basico'){empresas[i].plano='basico';empresas[i].planoStatus='ativo';empresas[i].planoAtivadoEm=new Date().toISOString();gravar('empregaMaisEmpresas',empresas);msg('#msgPlano','Plano Grátis ativado.',true);renderizarPlanosAtuais();return}const pedido={id:'plano_'+Date.now(),empresaCnpj:cnpj,empresa:empresas[i].nome,plano:p,valor:({mensal:49.9,trimestral:99,semestral:179.9,anual:329}[p]||0),status:'aguardando_pagamento',criadoEm:new Date().toISOString()};const pedidos=ler('empregaMaisPedidosPlano');pedidos.unshift(pedido);gravar('empregaMaisPedidosPlano',pedidos);empresas[i].planoPretendido=p;gravar('empregaMaisEmpresas',empresas);msg('#msgPlano','Plano '+PLANOS_EMPRESA[p].nome+' selecionado. Pedido registrado como aguardando pagamento.',true);renderizarPlanosAtuais()}
function renderizarPlanosAtuais(){if(papelAtual()!=='empresa')return;const c=sessionStorage.getItem('empresaCnpj'),e=ler('empregaMaisEmpresas').find(x=>x.cnpj===c),atual=e?.plano||'basico',pendentes=ler('empregaMaisPedidosPlano').filter(x=>x.empresaCnpj===c&&x.status==='aguardando_pagamento');document.querySelectorAll('.plano-card').forEach(card=>card.classList.remove('plano-atual'));document.querySelectorAll('.plano-card button').forEach(b=>{const m=(b.getAttribute('onclick')||'').match(/selecionarPlano\('([^']+)'\)/);if(!m)return;const p=m[1];b.disabled=false;b.textContent=p==='basico'?'Começar grátis':'Escolher plano';if(p===atual){b.closest('.plano-card')?.classList.add('plano-atual');b.textContent='Plano atual';b.disabled=true}else if(pendentes.some(x=>x.plano===p)){b.textContent='Aguardando pagamento';b.disabled=true}})}function ativarPedidoPlano(id){const ps=ler('empregaMaisPedidosPlano'),i=ps.findIndex(x=>x.id===id);if(i<0||ps[i].status==='ativo')return;const es=ler('empregaMaisEmpresas'),j=es.findIndex(e=>e.cnpj===ps[i].empresaCnpj);if(j<0)return;es[j].plano=ps[i].plano;es[j].planoStatus='ativo';es[j].planoAtivadoEm=new Date().toISOString();delete es[j].planoPretendido;ps.forEach((x,k)=>{if(k!==i&&x.empresaCnpj===ps[i].empresaCnpj&&x.status==='aguardando_pagamento')x.status='cancelado'});ps[i].status='ativo';ps[i].ativadoEm=new Date().toISOString();gravar('empregaMaisEmpresas',es);gravar('empregaMaisPedidosPlano',ps);adminAba('planos')}function planoEmpresaAtual(){const c=sessionStorage.getItem('empresaCnpj'),e=ler('empregaMaisEmpresas').find(x=>x.cnpj===c);return PLANOS_EMPRESA[e?.plano]||PLANOS_EMPRESA.basico}function chaveMes(d){const x=new Date(d||Date.now());return x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')}function usoPlanoEmpresa(){const c=sessionStorage.getItem('empresaCnpj')||'',mes=chaveMes(),vs=ler('empregaMaisVagas').filter(v=>v.empresaCnpj===c&&chaveMes(v.criadoEm)===mes&&v.status!=='excluida');return{vagas:vs.length,destaques:vs.filter(v=>v.destaque).length,urgentes:vs.filter(v=>v.urgente).length,confidenciais:vs.filter(v=>v.confidencial).length}}function saldoPlano(){const p=planoEmpresaAtual(),u=usoPlanoEmpresa();return{plano:p,uso:u,vagas:Math.max(0,p.vagas-u.vagas),destaques:Math.max(0,p.destaques-u.destaques),urgentes:Math.max(0,p.urgentes-u.urgentes),confidenciais:Math.max(0,p.confidenciais-u.confidenciais)}}function atualizarOpcoesPlano(){const x=saldoPlano(),set=(id,t)=>{const e=$('#'+id);if(e)e.textContent=t};set('saldoDestaque','('+x.destaques+' disponível(is) no mês)');set('saldoUrgente','('+x.urgentes+' disponível(is) no mês)');set('saldoConfidencial','('+x.confidenciais+' disponível(is) no mês)');const r=$('#resumoPlanoPublicacao');if(r)r.innerHTML='<strong>Plano '+x.plano.nome+'</strong><span>'+x.vagas+' de '+x.plano.vagas+' publicação(ões) disponível(is) neste mês</span>';[['vagaDestaque','destaques'],['vagaUrgente','urgentes'],['vagaConfidencial','confidenciais']].forEach(([id,k])=>{const e=$('#'+id);if(e&&!e.checked)e.disabled=x[k]<=0});const a=$('#avisoLimitePlano');if(a)a.textContent=x.vagas<=0?'Você atingiu o limite de publicações do seu plano neste mês.':''}function validarRecursosPlano(dados,editId){const x=saldoPlano(),lista=ler('empregaMaisVagas'),ant=editId?lista.find(v=>v.id===editId):null;if(!editId&&x.vagas<=0)return'Limite mensal de vagas atingido para o plano '+x.plano.nome+'.';if(dados.destaque&&!(ant&&ant.destaque)&&x.destaques<=0)return'Seu plano não possui Destaque disponível neste mês.';if(dados.urgente&&!(ant&&ant.urgente)&&x.urgentes<=0)return'Seu plano não possui marcação Urgente disponível neste mês.';if(dados.confidencial&&!(ant&&ant.confidencial)&&x.confidenciais<=0)return'Seu plano não possui vaga Confidencial disponível neste mês.';return''}

