function adminResolverDenuncia(id,status){const a=ler('empregaMaisDenuncias'),i=a.findIndex(d=>d.id===id);if(i<0)return;a[i].status=status;a[i].resolvidaEm=new Date().toISOString();gravar('empregaMaisDenuncias',a);adminAba('denuncias')}
function adminSuspenderDenuncia(id){const ds=ler('empregaMaisDenuncias'),i=ds.findIndex(d=>d.id===id);if(i<0)return;if(!confirm('Suspender esta vaga enquanto a denúncia é analisada?'))return;const vs=ler('empregaMaisVagas'),j=vs.findIndex(v=>v.id===ds[i].vagaId);if(j>=0){vs[j].status='suspensa';vs[j].suspensaEm=new Date().toISOString();vs[j].historicoModeracao=Array.isArray(vs[j].historicoModeracao)?vs[j].historicoModeracao:[];vs[j].historicoModeracao.push({acao:'Suspensa por denúncia',motivo:ds[i].motivo||'',data:vs[j].suspensaEm});gravar('empregaMaisVagas',vs)}ds[i].status='resolvida';ds[i].acao='vaga_suspensa';ds[i].resolvidaEm=new Date().toISOString();gravar('empregaMaisDenuncias',ds);adminAba('denuncias')}
function adminAba(aba,btn){if(sessionStorage.getItem('empregaMaisAdmin')!=='1'){irPara('login-admin');return}document.querySelectorAll('[data-admin-tab]').forEach(b=>b.classList.toggle('ativo',b.dataset.adminTab===aba));const out=$('#adminConteudo'),vs=ler('empregaMaisVagas'),es=ler('empregaMaisEmpresas'),cs=ler('empregaMaisCandidatos'),cands=candidaturas();if(aba==='geral'){const pend=vs.filter(v=>v.status==='pendente').length,apr=vs.filter(v=>v.status==='aprovada').length,contr=cands.filter(c=>grupoEtapa(c.status)==='Contratados').length;out.innerHTML='<div class="admin-metricas"><article><span>Vagas pendentes</span><strong>'+pend+'</strong></article><article><span>Vagas publicadas</span><strong>'+apr+'</strong></article><article><span>Empresas</span><strong>'+es.length+'</strong></article><article><span>Candidatos</span><strong>'+cs.length+'</strong></article><article><span>Contratações</span><strong>'+contr+'</strong></article></div><div class="admin-bloco"><h2>Aguardando aprovação</h2>'+adminTabelaVagas(vs.filter(v=>v.status==='pendente'))+'</div>';return}if(aba==='vagas'){out.innerHTML='<div class="admin-bloco"><h2>Todas as vagas</h2>'+adminTabelaVagas(vs)+'</div>';return}if(aba==='empresas'){out.innerHTML='<div class="admin-bloco"><div class="admin-titulo-acoes"><div><h2>Empresas cadastradas</h2><p class="admin-sub">Consulte cadastro, plano, vagas e contratações de cada empresa.</p></div></div>'+adminTabelaEmpresas(es,vs,cands)+'</div>';return}if(aba==='candidatos'){out.innerHTML='<div class="admin-bloco"><h2>Candidatos cadastrados</h2>'+adminTabelaPessoas(cs,'candidato')+'</div>';return}if(aba==='contratacoes'){const a=cands.filter(c=>grupoEtapa(c.status)==='Contratados');out.innerHTML='<div class="admin-bloco"><h2>Contratações registradas</h2>'+adminTabelaContratacoes(a)+'</div>';return}if(aba==='denuncias'){const ds=ler('empregaMaisDenuncias');out.innerHTML='<div class="admin-bloco"><h2>Denúncias de vagas</h2><p class="admin-sub">Analise os relatos enviados pelos usuários antes de tomar uma ação.</p>'+adminTabelaDenuncias(ds,vs)+'</div>';return}if(aba==='relatorios'){const aprov=vs.filter(v=>v.status==='aprovada').length,pend=vs.filter(v=>v.status==='pendente').length,enc=vs.filter(v=>v.status==='encerrada').length,contr=cands.filter(c=>grupoEtapa(c.status)==='Contratados').length,apps=cands.length,tx=apps?Math.round(contr/apps*100):0;const areas={};vs.forEach(v=>{const k=v.area||'Não informada';areas[k]=(areas[k]||0)+1});const top=Object.entries(areas).sort((a,b)=>b[1]-a[1]).slice(0,6);out.innerHTML='<div class="admin-bloco"><div class="admin-titulo-acoes"><div><h2>Relatórios do portal</h2><p class="admin-sub">Visão consolidada da operação registrada no EmpregaMais.</p></div></div><div class="relatorio-grid"><article><span>Vagas aprovadas</span><strong>'+aprov+'</strong></article><article><span>Em análise</span><strong>'+pend+'</strong></article><article><span>Encerradas</span><strong>'+enc+'</strong></article><article><span>Candidaturas</span><strong>'+apps+'</strong></article><article><span>Contratações</span><strong>'+contr+'</strong></article><article><span>Conversão em contratação</span><strong>'+tx+'%</strong></article></div><div class="relatorio-duplo"><section><h3>Vagas por área</h3>'+(top.length?top.map(([a,n])=>'<div class="relatorio-barra"><div><span>'+esc(a)+'</span><b>'+n+'</b></div><i><em style="width:'+Math.max(8,Math.round(n/Math.max(...top.map(x=>x[1]))*100))+'%"></em></i></div>').join(''):'<p>Sem dados.</p>')+'</section><section><h3>Resumo de cadastros</h3><div class="relatorio-lista"><div><span>Empresas cadastradas</span><b>'+es.length+'</b></div><div><span>Candidatos cadastrados</span><b>'+cs.length+'</b></div><div><span>Vagas totais</span><b>'+vs.length+'</b></div><div><span>Denúncias pendentes</span><b>'+ler('empregaMaisDenuncias').filter(d=>d.status==='pendente').length+'</b></div></div></section></div></div>';return}if(aba==='planos'){const pedidos=ler('empregaMaisPedidosPlano');out.innerHTML='<div class="admin-bloco"><h2>Planos das empresas</h2>'+adminPlanos(es)+'</div><div class="admin-bloco"><h2>Solicitações de planos</h2>'+(pedidos.length?'<div class="admin-lista">'+pedidos.map(p=>'<div class="admin-linha"><div><strong>'+esc(p.empresa||'Empresa')+'</strong><small>'+esc(PLANOS_EMPRESA[p.plano]?.nome||p.plano)+' · R$ '+Number(p.valor||0).toFixed(2).replace('.',',')+' · '+(p.status==='ativo'?'Ativo':'Aguardando pagamento')+'</small></div>'+(p.status!=='ativo'?'<button class="btn btn-azul" onclick="ativarPedidoPlano(\''+p.id+'\')">Confirmar pagamento e ativar</button>':'<span class="vaga-status aprovada">Ativo</span>')+'</div>').join('')+'</div>':'<div class="vagas-vazio">Nenhuma solicitação de plano.</div>')+'</div>';return}const p=e.perfil||{};$('#empresaPublicaNome').textContent=p.nome||e.nome||'Empresa';$('#empresaPublicaSlogan').textContent=p.slogan||'';const img=$('#empresaPublicaLogo');if(p.logo){img.src=p.logo;img.style.display='block'}else img.style.display='none';const capa=$('#empresaPublicaCapa');capa.style.backgroundImage=p.capa?'url("'+p.capa.replace(/"/g,'')+'")':'';$('#empresaPublicaInfo').innerHTML='<div><span>Matriz</span><strong>'+esc((p.cidade||e.cidade||'')+(p.uf||e.uf?' - '+(p.uf||e.uf):''))+'</strong></div><div><span>Funcionários</span><strong>'+esc(p.porte||'Não informado')+'</strong></div><div><span>Setor</span><strong>'+esc(p.segmento||'Não informado')+'</strong></div><div><span>Fundação</span><strong>'+esc(p.fundacao||'Não informado')+'</strong></div>';$('#empresaPublicaSobre').textContent=p.sobre||'A empresa ainda não adicionou uma apresentação.';$('#empresaPublicaInstitucional').innerHTML=[['Missão',p.missao],['Visão',p.visao],['Valores',p.valores],['Cultura',p.cultura],['Ambiente e jeito de trabalhar',p.ambiente],['Benefícios',p.beneficios],['Carreira e desenvolvimento',p.carreira],['Modalidades de trabalho',p.modalidades],['Áreas que mais contratam',p.areas]].filter(x=>x[1]).map(x=>'<h3>'+x[0]+'</h3><p>'+esc(x[1])+'</p>').join('');const links=$('#empresaPublicaLinks');if(links){const arr=[['Site',p.site],['LinkedIn',p.linkedin],['Instagram',p.instagram],['Facebook',p.facebook],['Vídeo institucional',p.video],['E-mail',p.emailPublico?'mailto:'+p.emailPublico:'']].filter(x=>x[1]);links.innerHTML=arr.map(x=>'<a class="btn" target="_blank" rel="noopener" href="'+esc(x[1])+'">'+x[0]+'</a>').join('')} const vs=ler('empregaMaisVagas').filter(v=>v.status==='aprovada'&&(v.empresaCnpj===c||v.cnpj===c)&&!v.confidencial);$('#empresaPublicaQtd').textContent=vs.length;$('#empresaPublicaVagas').innerHTML=vs.length?vs.map(v=>'<article class="vaga-card portal-vaga" onclick="abrirVaga(\''+v.id+'\')"><span class="tag">'+esc(v.modalidade||'Vaga')+'</span><h3>'+esc(tituloVaga(v))+'</h3><p>'+esc(v.cidade||'')+'</p></article>').join(''):'<div class="vagas-vazio">Nenhuma vaga aberta no momento.</div>'}

function renderizarVagasSenior(){const box=$('#listaVagasSenior');if(!box)return;const a=vagasPublicas().filter(v=>v.senior50);box.innerHTML=a.length?a.map(v=>'<article class="vaga-card portal-vaga" onclick="abrirVaga(\''+v.id+'\')"><span class="tag">50+</span><h3>'+esc(tituloVaga(v))+'</h3><p>'+esc(v.confidencial?'Empresa confidencial':v.empresa||'')+'</p><div class="vaga-meta"><span>'+esc(v.cidade||'')+'</span><span>'+esc(v.modalidade||'')+'</span></div></article>').join(''):'<div class="vagas-vazio"><strong>Nenhuma vaga 50+ publicada agora</strong><span>Novas oportunidades aparecerão aqui quando forem aprovadas.</span></div>'}
function filtrarSenior(){renderizarVagasSenior();document.querySelector('#listaVagasSenior')?.scrollIntoView({behavior:'smooth'})}

